"""Focused MySQL 8.0.28 exam explanations; examples have no persistent writes."""


def T(number, question, answer, tags, example, pattern='computed'):
    return dict(id='TH3-%03d' % number, question=question, answer=answer,
                tags=tags.split('|'), examples=[example] if example else [],
                pattern=pattern, mistakes=[])


THEORY3 = [
 T(1, 'Why does LAST_VALUE need an explicit full-partition frame to return the final row?',
   'With window ORDER BY, the default frame ends at the current row and its peers, so LAST_VALUE normally sees only that prefix. Use ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING for the partition final value. Add a unique tie-breaker to ORDER BY when final-row identity matters; this works in MySQL 8.0.28.',
   'last_value|full partition|window frame',
   'SELECT `Order ID`,LAST_VALUE(`Order ID`) OVER (ORDER BY `Order Date`,`Order ID` ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM orders;', 'topn_rank'),
 T(2, 'How do ROWS and default RANGE frames differ for running totals with duplicate sort keys?',
   'ROWS counts physical rows in the specified window order; RANGE groups peers with equal ordering values at a CURRENT ROW boundary. With ORDER BY and no explicit frame, aggregate windows default to RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, so tied dates receive the same cumulative total. For one-order-at-a-time accumulation specify ROWS and a unique ordering key.',
   'rows|range|peers|running total',
   'SELECT `Order ID`,SUM(`Shipping Fee`) OVER (ORDER BY `Order Date`) peer_total,SUM(`Shipping Fee`) OVER (ORDER BY `Order Date`,`Order ID` ROWS UNBOUNDED PRECEDING) row_total FROM orders;', 'topn_rank'),
 T(3, 'How can a MySQL 8.0.28 query filter a computed window rank without QUALIFY?',
   'Window results are computed after WHERE and HAVING, so neither can directly filter a rank from that same SELECT level. Put the ranking SELECT in a CTE or derived table and filter its alias in an outer WHERE. MySQL 8.0.28 has no QUALIFY clause.',
   'qualify|window rank|outer where|cte',
   'WITH ranked AS (SELECT ID,ROW_NUMBER() OVER (ORDER BY `List Price` DESC,ID) position FROM products) SELECT ID FROM ranked WHERE position<=3;', 'topn_rank'),
 T(4, 'What is the NULL-safe equality operator <=>, including NULL-to-NULL comparisons?',
   'In MySQL, <=> returns 1 when both operands are NULL and 0 when only one is NULL; it otherwise tests equality. Ordinary = produces UNKNOWN when either operand is NULL. Use <=> only when two missing values should count as matching, for example joining aggregated nullable category keys.',
   'null-safe equality|<=>|null comparison',
   'SELECT NULL<=>NULL, NULL<=>1, 1<=>1, NULL=NULL;', 'null_handling'),
 T(5, 'Does a NULL inside NOT IN always make every candidate UNKNOWN, even when a value matches?',
   'No: a matching value makes IN true and NOT IN false, even if another list element is NULL. When no value matches but the list contains NULL, IN and NOT IN are UNKNOWN, so WHERE rejects that row. Prefer NOT EXISTS for an anti-join when NULLs may occur, while separately deciding how a NULL outer key should behave.',
   'not in|truth table|null|matching value',
   'SELECT 1 NOT IN (1,NULL),2 NOT IN (1,NULL),NULL NOT IN (1,2);', 'not_exists'),
 T(6, 'What are the empty-set and NULL rules for quantified ALL and ANY comparisons?',
   'ALL over no rows is true; ANY over no rows is false, including when the left operand is NULL. For a nonempty set, a false comparison defeats ALL and a true comparison satisfies ANY; otherwise a NULL comparison can leave UNKNOWN. Replacing > ALL by > MAX or > ANY by > MIN requires explicit assumptions about empty sets and NULLs.',
   'all|any|empty set|null semantics',
   'SELECT NULL>ALL(SELECT `List Price` FROM products WHERE 1=0),NULL>ANY(SELECT `List Price` FROM products WHERE 1=0),2>ALL(SELECT value FROM (SELECT 1 value UNION ALL SELECT NULL) valueset);', 'all_any'),
 T(7, 'Why do sums inflate when order details and invoices are both joined to orders?',
   'Two independent one-to-many joins form every matching detail/invoice combination for an order. An order with three details and two invoices creates six rows, duplicating both monetary measures. Aggregate each child to one row per order before joining, or use independent correlated aggregates; DISTINCT on the final displayed rows does not repair the sums.',
   'fanout|double counting|detail invoice|preaggregate',
   'SELECT ord.`Order ID`,(SELECT COUNT(*) FROM `order details` line WHERE line.`Order ID`=ord.`Order ID`),(SELECT COUNT(*) FROM invoices invoice WHERE invoice.`Order ID`=ord.`Order ID`) FROM orders ord;', 'left_join'),
 T(8, 'Why is SUM(DISTINCT monetary_amount) not a general solution to join double counting?',
   'DISTINCT applies to amount values, not to the identities of legitimate rows. Two different lines costing the same amount must both contribute, but SUM(DISTINCT amount) counts that amount once. Remove duplication at the business-key grain or preaggregate child tables instead.',
   'sum distinct|equal amounts|fanout|business key',
   'SELECT SUM(amount),SUM(DISTINCT amount) FROM (SELECT 10 amount UNION ALL SELECT 10 UNION ALL SELECT 20) amounts;', 'aggregate'),
 T(9, 'When does ONLY_FULL_GROUP_BY accept columns functionally dependent on a grouped key?',
   'MySQL 8.0.28 can accept selected nonaggregated columns when it proves they are functionally dependent on the grouping columns, such as grouping a table by its primary key. A UNIQUE NOT NULL key can also establish dependence; a nullable unique key does not generally give the same guarantee. Grouping by a nonunique descriptive label does not determine the other columns merely because the current sample happens to be unique.',
   'functional dependence|only_full_group_by|unique not null',
   'SELECT ID,`Product Name`,MAX(`List Price`) FROM products GROUP BY ID;', 'group_having'),
 T(10, 'Does ANY_VALUE choose a latest or deterministic representative row for a group?',
   'ANY_VALUE suppresses the ONLY_FULL_GROUP_BY check for its argument; it does not select a business-defined representative. The chosen value need not come from the row with the greatest date, and an outer ORDER BY cannot make that choice deterministic. Use a ranked subquery or a join to a computed extremum when row identity matters.',
   'any_value|arbitrary representative|determinism',
   'SELECT Category,ANY_VALUE(`Product Name`),MAX(`List Price`) FROM products GROUP BY Category;', 'group_having'),
 T(11, 'What limits recursive CTE depth and growing text width in MySQL 8.0.28?',
   'Recursive CTE column types are inferred from the nonrecursive member, so cast an anchor string to a sufficient width before growing a path. Terminate recursion with a predicate; cte_max_recursion_depth defaults to 1000 recursive levels but can be configured. A finite demonstration does not establish that an arbitrary hierarchy is cycle-free.',
   'recursive cte|anchor width|recursion depth|cast',
   "WITH RECURSIVE paths AS (SELECT 1 depth,CAST('x' AS CHAR(10)) path UNION ALL SELECT depth+1,CONCAT(path,'x') FROM paths WHERE depth<3) SELECT depth,path FROM paths;", 'subquery'),
 T(12, 'Can LAG or LEAD skip NULL values with IGNORE NULLS in MySQL 8.0.28?',
   'No: MySQL 8.0.28 supports RESPECT NULLS, not IGNORE NULLS; the latter is recognized but rejected. LAG therefore reads the preceding row even when its value is NULL, and its default argument applies to a missing row, not to a NULL value in an existing row. For previous non-NULL data, filter observations before the window when dropping NULL rows is acceptable, or use a correlated lookup with an explicit ordering rule.',
   'lag|lead|ignore nulls|respect nulls',
   'SELECT `Order ID`,LAG(`Shipped Date`,1) OVER (ORDER BY `Order ID`) FROM orders;', 'topn_rank'),
 T(13, 'How do you obtain a distinct count per window partition when MySQL rejects COUNT(DISTINCT ...) OVER?',
   'MySQL 8.0.28 does not support DISTINCT aggregate window functions. Compute COUNT(DISTINCT value) with GROUP BY and join the totals back if every original row must remain, or deduplicate the partition/value pairs before a COUNT window when only unique pairs are needed. Decide explicitly whether NULL values should count; COUNT(DISTINCT value) excludes them.',
   'distinct window|count distinct|partition|preaggregate',
   'WITH counts AS (SELECT `Customer ID` customer_id,COUNT(DISTINCT `Employee ID`) quantity FROM orders GROUP BY `Customer ID`) SELECT ord.`Order ID`,counts.quantity FROM orders ord JOIN counts ON counts.customer_id<=>ord.`Customer ID`;', 'topn_rank'),
 T(14, 'Why does COUNT(CASE WHEN predicate THEN 1 ELSE 0 END) count false cases too?',
   'COUNT(expression) counts every non-NULL expression result, including zero. Use SUM(CASE WHEN predicate THEN 1 ELSE 0 END) or COUNT(CASE WHEN predicate THEN 1 END) for conditional counts. On an empty input the SUM is NULL while COUNT is zero, so apply COALESCE to SUM if the desired display is zero.',
   'conditional count|case else zero|count versus sum',
   'SELECT COUNT(CASE WHEN `Shipped Date` IS NOT NULL THEN 1 ELSE 0 END),COUNT(CASE WHEN `Shipped Date` IS NOT NULL THEN 1 END),SUM(CASE WHEN `Shipped Date` IS NOT NULL THEN 1 ELSE 0 END) FROM orders;', 'cond_agg'),
 T(15, 'How does MySQL COUNT(DISTINCT column1, column2) handle NULL components?',
   'The multi-expression form counts distinct combinations only when every component is non-NULL. A row with NULL in either expression is ignored, rather than counted as a special pair. To count nullable combinations as groups, first SELECT DISTINCT both columns and then COUNT(*) over that derived relation.',
   'count distinct pair|null components|nullable combinations',
   'SELECT COUNT(DISTINCT left_number,right_number) FROM (SELECT 1 left_number,2 right_number UNION ALL SELECT 1,NULL UNION ALL SELECT 1,2) pairs;', 'null_handling'),
 T(16, 'Do nullable foreign keys guarantee a matching parent, and does this Northwind dump enforce them?',
   'A nullable foreign key allows missing references: in MySQL a composite foreign key is exempt from a parent match when any component is NULL. A declared foreign key enforces known references only when the relevant engine and settings enforce the constraint. This dump declares no foreign keys, so column names and plausible joins are not proof of referential integrity; validate relationships against the data.',
   'nullable foreign key|dump integrity|composite key',
   'SELECT COUNT(*) FROM orders ord LEFT JOIN customers customer ON customer.ID=ord.`Customer ID` WHERE ord.`Customer ID` IS NOT NULL AND customer.ID IS NULL;', 'inner_join'),
 T(17, 'Should invoice calculations round each line before summing or round only the final total?',
   'Those policies are not mathematically equivalent: several sub-cent fractions can produce a different total when rounded per line. Follow the question or accounting policy; if unspecified, state the choice and normally retain exact DECIMAL precision until final display. Never claim that a line subtotal must equal stored Amount Due without understanding tax, shipping and discount rules.',
   'rounding policy|invoice|line rounding|decimal precision',
   'SELECT SUM(ROUND(amount,2)),ROUND(SUM(amount),2) FROM (SELECT CAST(0.004 AS DECIMAL(8,3)) amount UNION ALL SELECT 0.004 UNION ALL SELECT 0.004) amounts;', 'computed'),
 T(18, 'How does keyset pagination differ from OFFSET when concurrent inserts can move page boundaries?',
   'Keyset pagination selects rows after the last seen ordering tuple, for example (Order Date, Order ID), instead of skipping a changing row count. Include a unique tie-breaker and use a matching inequality for the sort direction. It reduces shifted boundaries and deep-offset scanning, but does not create a fixed snapshot; NULL sort keys and changes to sort values need an explicit policy.',
   'keyset pagination|seek|offset|concurrent inserts',
   "SELECT `Order ID`,`Order Date` FROM orders WHERE (`Order Date`,`Order ID`) > ('2006-03-01',30) ORDER BY `Order Date`,`Order ID` LIMIT 5;", 'order_limit'),
 T(19, 'How do you group ISO weeks correctly across a calendar-year boundary?',
   'A week number alone merges years and the ISO week-year can differ from YEAR(date) around New Year. Use YEARWEEK(date,3), or DATE_FORMAT(date,\'%x-%v\') for a Monday-first ISO week-year label. Do not combine YEAR(date) with WEEK(date,3) and assume it is the ISO week-year.',
   'iso week|yearweek|week-year|new year',
   "SELECT YEARWEEK('2021-01-01',3),DATE_FORMAT('2021-01-01','%x-%v'),YEAR('2021-01-01');", 'date'),
 T(20, 'Does TIMESTAMPDIFF measure complete units, and which argument order determines its sign?',
   'TIMESTAMPDIFF(unit, start, end) returns an integer count of complete units from start to end, truncating a fractional result toward zero. Reversing the endpoints reverses the signed interval; this argument order is opposite to DATEDIFF(end,start). For months or years it is a calendar-unit calculation, not a fixed number of seconds.',
   'timestampdiff|complete units|argument order|negative interval',
   "SELECT TIMESTAMPDIFF(HOUR,'2006-03-01 00:30:00','2006-03-01 02:00:00'),TIMESTAMPDIFF(HOUR,'2006-03-01 02:00:00','2006-03-01 00:30:00');", 'date'),
 T(21, 'Why can subtracting one month from a date and then adding it back change the date?',
   'DATE_ADD and DATE_SUB clamp a day to the last valid day of the destination month. Thus a month-end date can lose its original day number during a round trip. Generate month calendars from first-of-month anchors rather than repeatedly stepping from a late day.',
   'date_add|month-end clamp|calendar anchor',
   "SELECT DATE_ADD('2006-01-31',INTERVAL 1 MONTH),DATE_SUB(DATE_ADD('2006-01-31',INTERVAL 1 MONTH),INTERVAL 1 MONTH);", 'date'),
 T(22, 'How can you distinguish calendar-day shipment delay from elapsed full-day delay?',
   'DATEDIFF ignores time-of-day, so crossing midnight can count one day even when only a minute elapsed. TIMESTAMPDIFF(DAY,start,end) counts full day units in the stored datetime interval. State which interpretation the question needs; neither automatically counts business days or holidays.',
   'calendar days|elapsed days|midnight|shipment delay',
   "SELECT DATEDIFF('2006-03-02 00:00:00','2006-03-01 23:59:00'),TIMESTAMPDIFF(DAY,'2006-03-01 23:59:00','2006-03-02 00:00:00');", 'date'),
 T(23, 'What does DATETIME(6) precision mean, and can a 23:59:59 end-of-day filter miss values?',
   'The fractional-seconds precision for DATETIME, TIMESTAMP and TIME ranges from zero to six, with six retaining microseconds and omitted precision defaulting to zero. A value later than 23:59:59 can therefore still belong to that calendar date. Use an exclusive next-day boundary rather than guessing the final stored fraction; changing precision may round fractional input according to SQL mode.',
   'datetime microseconds|fractional precision|fsp six',
   "SELECT CAST('2006-03-31 23:59:59.123456' AS DATETIME(6))>CAST('2006-03-31 23:59:59' AS DATETIME(6));", 'date'),
 T(24, 'How does session time_zone affect TIMESTAMP and explicit timezone conversion?',
   'MySQL converts TIMESTAMP values between the session time zone and UTC for storage/retrieval; DATETIME does not perform that automatic conversion. CONVERT_TZ can convert an explicit datetime when source and destination zones are known. Named zones require populated timezone tables, whereas literal offsets avoid that dependency but do not model daylight-saving rules.',
   'time_zone|timestamp|convert_tz|timezone tables',
   "SELECT @@session.time_zone,CONVERT_TZ('2006-03-01 00:00:00','+00:00','+07:00');", 'date'),
 T(25, 'When does COALESCE(SUM(value),0) conceal missing data rather than merely display an empty total?',
   'SUM is NULL both when there are no input rows and when every input value is NULL. COALESCE changes both cases to zero, which is appropriate only if the interpretation permits unknown values to be displayed as zero. Include COUNT(*) and COUNT(value) when the distinction between no observations, unknown observations and genuine zero matters.',
   'coalesce sum|unknown versus zero|empty aggregate',
   'SELECT COUNT(*),COUNT(`Due Date`),SUM(`Amount Due`),COALESCE(SUM(`Amount Due`),0) FROM invoices;', 'null_handling'),
 T(26, 'Can COALESCE or CASE change an expression type when numeric and string branches are mixed?',
   'The result type is derived from the participating expressions, not simply from the branch chosen on one row. Mixing numbers and text can therefore yield a string result and affect sorting or later numeric conversion. Use an explicit CAST and consistent branch types when numeric precision or lexical ordering matters.',
   'coalesce type|case coercion|cast|mixed branches',
   "SELECT COALESCE(NULL,CAST(12.5 AS DECIMAL(8,2))),CASE WHEN 1=1 THEN CAST(12.5 AS DECIMAL(8,2)) ELSE CAST(0 AS DECIMAL(8,2)) END;", 'computed'),
 T(27, 'Does TRIM remove tabs, newlines and all Unicode whitespace by default?',
   'No: default TRIM removes leading and trailing space characters, not arbitrary whitespace. Specify the removal string for a particular character, or use a carefully chosen regular expression when a broader whitespace rule is intended. Do not silently equate empty strings, spaces and NULL in cleaning rules.',
   'trim|tab|whitespace|data cleaning',
   "SELECT CHAR_LENGTH(TRIM(CONCAT(CHAR(9),' x ',CHAR(9)))),CHAR_LENGTH(TRIM(' x '));", 'string_funcs'),
 T(28, 'Can equality ignore trailing spaces under one collation but preserve them under another?',
   'Yes: PAD SPACE collations ignore trailing pad spaces in string comparisons, while NO PAD collations treat them as significant. MySQL 8.0 utf8mb4_0900_ai_ci is NO PAD; older utf8mb4_general_ci is PAD SPACE. Inspect the selected collation instead of assuming all VARCHAR comparisons have identical trailing-space behavior.',
   'pad space|no pad|collation|trailing spaces',
   "SELECT _utf8mb4'x' COLLATE utf8mb4_general_ci = _utf8mb4'x ' COLLATE utf8mb4_general_ci,_utf8mb4'x' COLLATE utf8mb4_0900_ai_ci = _utf8mb4'x ' COLLATE utf8mb4_0900_ai_ci;", 'string_funcs'),
 T(29, 'How can LIKE match a literal underscore or percent without relying on backslash SQL-mode behavior?',
   'In LIKE, underscore matches one character and percent matches a sequence, so escape them when literal characters are intended. An explicit ESCAPE character such as ! makes the pattern rule visible and avoids confusion with backslashes in string literals and NO_BACKSLASH_ESCAPES. To match the escape character itself, repeat it in the pattern.',
   'like literal underscore|escape percent|no_backslash_escapes',
   "SELECT 'A_B' LIKE 'A!_B' ESCAPE '!', 'A%B' LIKE 'A!%B' ESCAPE '!', 'A!B' LIKE 'A!!B' ESCAPE '!';", 'string_funcs'),
 T(30, 'Which regular expression features are available for text cleanup in MySQL 8.0.28?',
   'MySQL 8.0 uses ICU-based regular expressions and provides REGEXP_LIKE, REGEXP_INSTR, REGEXP_SUBSTR and REGEXP_REPLACE. These functions are available on 8.0.28; do not confuse them with older MySQL releases that only offered the REGEXP predicate. Choose case sensitivity explicitly with match_type when required, and remember that regular-expression syntax differs from LIKE wildcards.',
   'icu|regexp_replace|regexp_substr|mysql version',
   "SELECT REGEXP_REPLACE('A-12 B','[^0-9]',''),REGEXP_LIKE('Abc','^a','i');", 'string_funcs'),
 T(31, 'Why should a semicolon-delimited Supplier IDs string not be joined to suppliers.ID with equality?',
   'The text column can represent several suppliers, so numeric coercion or whole-string equality is not a relationship join. Prefer a normalized junction table; for a read-only exercise, parse tokens and compare complete trimmed identifiers, not substrings that confuse 1 with 11. Purchase-order supplier history is a different fact and must not be substituted silently for the catalogue supplier list.',
   'supplier ids|semicolon list|normalization|token matching',
   "SELECT ID,`Supplier IDs` FROM products WHERE LOCATE(';',`Supplier IDs`)>0;", 'inner_join'),
 T(32, 'How can GROUP_CONCAT lose data or give unstable text order?',
   'GROUP_CONCAT ignores NULL expressions and can truncate its result at group_concat_max_len, so it is not a lossless general-purpose storage format. Put ORDER BY inside GROUP_CONCAT for deterministic element order; an outer ORDER BY orders groups, not their members. Choose a safe encoding if values may contain the separator.',
   'group_concat truncation|group_concat_max_len|element order',
   "SELECT Category,GROUP_CONCAT(ID ORDER BY ID SEPARATOR ',') FROM products GROUP BY Category;", 'aggregate'),
 T(33, 'Does grouped JSON_ARRAYAGG guarantee input order in MySQL 8.0.28?',
   'The grouped aggregate does not promise array element order, so a preceding subquery ORDER BY alone is not a reliable ordering contract. If sequence matters, use a supported ordered window formulation with an explicit frame and select the intended output row, or order the relational rows before presentation outside the aggregate. JSON_ARRAYAGG includes JSON null elements for SQL NULL inputs, unlike GROUP_CONCAT which skips NULL expressions.',
   'json_arrayagg|undefined order|json null',
   'SELECT JSON_ARRAYAGG(value) FROM (SELECT 1 value UNION ALL SELECT NULL) valueset;', 'aggregate'),
 T(34, 'How do JSON null and a missing JSON path differ from SQL NULL?',
   'JSON null is a JSON value; a missing path extracted by JSON_EXTRACT yields SQL NULL. JSON_TYPE on an extracted JSON null reports the string NULL, while IS NULL on a missing extraction is true. Use JSON_CONTAINS_PATH when existence matters independently of the stored JSON value.',
   'json null|missing path|sql null|json_type',
   "SELECT JSON_TYPE(JSON_EXTRACT('{\"present\":null}','$.present')),JSON_EXTRACT('{\"present\":null}','$.missing') IS NULL,JSON_CONTAINS_PATH('{\"present\":null}','one','$.present');", 'null_handling'),
 T(35, 'How can JSON_TABLE turn an array into relational rows on the exam version?',
   'JSON_TABLE is available before MySQL 8.0.28 and exposes array elements through declared COLUMNS and path expressions, with FOR ORDINALITY for positions. Specify ON EMPTY and ON ERROR behavior when conversion or missing paths matter. Since 8.0.21, a source JSON null maps to SQL NULL rather than the earlier error behavior.',
   'json_table|ordinality|8.0.21|array rows',
   "SELECT parsed.position,parsed.value FROM JSON_TABLE('[4,null,7]','$[*]' COLUMNS(position FOR ORDINALITY,value INT PATH '$' NULL ON EMPTY NULL ON ERROR)) parsed;", 'inner_join'),
 T(36, 'Where do UNION result column names come from and where should final ORDER BY be placed?',
   'The combined result uses column names from the first query block; later aliases do not rename the output. Apply a final ORDER BY to the combined result and refer to its output names, not a table alias confined to one branch. Branch-local ordering does not guarantee the final union order; use compatible column positions and types.',
   'union column names|final order by|branch alias',
   "SELECT Company label FROM customers UNION SELECT Company other_label FROM suppliers ORDER BY label;", 'set_ops'),
 T(37, 'Should a NULL required member count in relational division?',
   'That is a modeling choice, not a property that COUNT and NOT EXISTS automatically agree on. COUNT(DISTINCT value) ignores NULL, while a double NOT EXISTS formulation using ordinary equality may treat a NULL requirement as an unmatchable counterexample. Exclude NULL members in both formulations or use NULL-safe equality and a counting scheme that includes the NULL member.',
   'division|null requirement|vacuous truth|count distinct',
   'SELECT product.ID FROM products product WHERE NOT EXISTS (SELECT 1 FROM products required WHERE required.Category IS NOT NULL AND required.Category=product.Category AND required.ID<>product.ID);', 'division'),
 T(38, 'Why must a zero-inclusive report start from a parent set or calendar rather than only from transaction rows?',
   'GROUP BY cannot invent a group with no input records. Start with all required parents or a generated calendar and LEFT JOIN qualifying facts, keeping fact filters in ON. Count a nonnullable fact key so an unmatched placeholder is zero, not one; missing money may require COALESCE under a stated policy.',
   'zero-inclusive report|calendar|missing groups|left join',
   'SELECT product.ID,COUNT(line.ID) FROM products product LEFT JOIN `order details` line ON line.`Product ID`=product.ID GROUP BY product.ID;', 'left_join'),
 T(39, 'How can MySQL 8.0.28 compute a median without PERCENTILE_CONT?',
   'MySQL 8.0.28 has no built-in PERCENTILE_CONT ordered-set aggregate. Sort the non-NULL observations with ROW_NUMBER, count them, and average the central one or two values. Define whether repeated observations count; the ordinary sample median includes duplicates rather than taking distinct values.',
   'median|percentile_cont|central rows|row_number',
   'WITH numbered AS (SELECT `List Price` price,ROW_NUMBER() OVER (ORDER BY `List Price`,ID) position,COUNT(*) OVER () quantity FROM products WHERE `List Price` IS NOT NULL) SELECT AVG(price) FROM numbered WHERE position IN ((quantity+1) DIV 2,(quantity+2) DIV 2);', 'topn_rank'),
 T(40, 'How do population and sample standard deviation differ for one-row groups?',
   'STDDEV_POP divides by the population count and returns zero for one known observation; STDDEV_SAMP uses the sample correction and returns NULL when fewer than two known observations exist. Both ignore NULL values and return NULL when no known observations remain. State whether deviation means standard deviation or signed distance from an average before choosing a function.',
   'stddev_pop|stddev_samp|deviation|one observation',
   'SELECT STDDEV_POP(value),STDDEV_SAMP(value) FROM (SELECT 12 value) observation;', 'aggregate'),
 T(41, 'Does adding ID to a DENSE_RANK window preserve price ties?',
   'No: peers are equal across every expression in the window ORDER BY. Adding a unique ID makes equal-price rows nonpeers and changes DENSE_RANK into distinct row positions for those rows. Rank by price alone when ties must survive, and put ID only in the final display ORDER BY; use ROW_NUMBER with ID when a fixed row count is intended.',
   'dense_rank tie breaker|peer identity|price ties',
   'SELECT ID,`List Price`,DENSE_RANK() OVER (ORDER BY `List Price` DESC),DENSE_RANK() OVER (ORDER BY `List Price` DESC,ID) FROM products;', 'topn_rank'),
 T(42, 'Does an ORDER BY inside a CTE guarantee the outer query row order?',
   'No: a CTE or derived table is a relational input, and an outer SELECT needs its own ORDER BY for a guaranteed display sequence. Internal ordering may have meaning with LIMIT or window calculations, but it is not a general promise about outer output order. Specify a unique tie-breaker if reproducible pagination or snapshots matter.',
   'cte order|derived order|outer order by|determinism',
   'WITH selected AS (SELECT ID,`List Price` FROM products ORDER BY `List Price` DESC LIMIT 5) SELECT ID,`List Price` FROM selected ORDER BY `List Price` DESC,ID;', 'order_limit'),
 T(43, 'Must every CTE be materialized, and can you infer its performance from WITH syntax?',
   'No: MySQL may merge a nonrecursive CTE or derived table into the outer query, or materialize it depending on its structure and optimizer decisions. Recursion, aggregation and window functions can prevent merging. Use EXPLAIN for the actual query and server version instead of claiming WITH inherently caches results or is always faster.',
   'cte merge|materialization|explain|optimizer',
   'EXPLAIN WITH selected AS (SELECT ID,Category FROM products) SELECT ID FROM selected WHERE Category=\'Beverages\';', 'optimization'),
 T(44, 'What does a LATERAL derived table allow in MySQL 8.0.28?',
   'LATERAL allows a derived table to reference preceding tables in the same FROM clause, making a per-parent lookup or aggregate expressible there. It is supported since MySQL 8.0.14, so it is valid on 8.0.28; it is not a guarantee of a faster plan. LEFT JOIN LATERAL with ON TRUE can preserve a parent when the dependent query returns no rows.',
   'lateral derived|correlated from|8.0.14',
   'SELECT customer.ID,recent.order_id FROM customers customer LEFT JOIN LATERAL (SELECT ord.`Order ID` order_id FROM orders ord WHERE ord.`Customer ID`=customer.ID ORDER BY ord.`Order Date` DESC,ord.`Order ID` DESC LIMIT 1) recent ON TRUE;', 'inner_join'),
 T(45, 'What extra information does EXPLAIN ANALYZE provide and is it supported on 8.0.28?',
   'EXPLAIN ANALYZE executes a supported query and reports actual iterator timing, rows and loops, unlike plain EXPLAIN estimates. It has been available since MySQL 8.0.18 and uses TREE output on 8.0.28. Because it executes the query, do not treat it as a harmless substitute for reviewing expensive or state-changing SQL.',
   'explain analyze|actual rows|tree|8.0.18',
   'EXPLAIN ANALYZE SELECT ID FROM products WHERE Category=\'Beverages\';', 'optimization'),
 T(46, 'Can a functional index help a function-wrapped predicate on MySQL 8.0.28?',
   'Functional key parts have been supported since MySQL 8.0.13, so an index on a suitable expression can help a matching expression predicate. Therefore it is too absolute to say a function on a column can never use an index. A plain date range is often simpler for YEAR(date) filtering, but always inspect the real index definition and plan.',
   'functional index|expression index|sargability|8.0.13',
   'EXPLAIN SELECT `Order ID` FROM orders WHERE YEAR(`Order Date`)=2006;', 'optimization'),
 T(47, 'What is an invisible index and does making it invisible remove write overhead?',
   'An invisible index remains maintained and stored but is normally ignored by the optimizer unless its use is enabled explicitly. It can help test the plan impact of removing an index without immediately dropping it. It does not remove insertion/update cost or storage usage, and MySQL does not permit an invisible primary key.',
   'invisible index|maintenance overhead|optimizer',
   'SHOW INDEX FROM orders;', 'optimization'),
 T(48, 'Does a CHECK constraint reject UNKNOWN and was CHECK always enforced in MySQL 8.0?',
   'A CHECK condition accepts TRUE or UNKNOWN and rejects FALSE, so CHECK(price > 0) alone does not prohibit NULL; add NOT NULL when required. MySQL began enforcing CHECK constraints in 8.0.16; earlier 8.0 versions parsed and ignored them. The exam version 8.0.28 supports enforced checks, subject to their expression restrictions.',
   'check unknown|not null|8.0.16|constraint enforcement',
   'SELECT (NULL>0) IS UNKNOWN,(0>0) IS FALSE,(1>0) IS TRUE;', 'null_handling'),
 T(49, 'What is atomic DDL, and does it mean CREATE TABLE can be rolled back by the user?',
   'For supported InnoDB operations, atomic DDL coordinates dictionary, storage-engine and binary-log work so a crash does not leave a partially applied statement. That is not user transaction rollback support: ordinary DDL generally commits implicitly. CREATE TEMPORARY TABLE and DROP TEMPORARY TABLE do not implicitly commit, but their table creation/deletion still is not undone by ROLLBACK.',
   'atomic ddl|implicit commit|temporary table rollback',
   'SELECT @@default_storage_engine,@@autocommit;', 'transaction'),
 T(50, 'Does ROLLBACK TO SAVEPOINT end the transaction or release every lock?',
   'ROLLBACK TO SAVEPOINT undoes transactional changes after the named savepoint without ending the transaction. It is not equivalent to a full ROLLBACK and does not promise to release all locks acquired after that point. RELEASE SAVEPOINT removes the marker without committing the transaction or undoing data.',
   'rollback to savepoint|locks|release savepoint',
   'START TRANSACTION; SAVEPOINT before_work; SELECT COUNT(*) FROM orders; ROLLBACK TO SAVEPOINT before_work; RELEASE SAVEPOINT before_work; ROLLBACK;', 'transaction'),
 T(51, 'Why does SELECT FOR UPDATE need an explicit transaction for a read-then-write workflow?',
   'An InnoDB locking read holds relevant locks for its transaction, but an autocommit statement ends its transaction immediately. Put the read and dependent write in one explicit transaction and use an indexed, appropriately selective predicate to limit locking. Ordinary snapshot reads are not a substitute for locking reads when enforcing a concurrent read-modify-write invariant.',
   'for update|locking read|autocommit|read modify write',
   'START TRANSACTION; SELECT `Order ID` FROM orders WHERE `Order ID`=30 FOR UPDATE; ROLLBACK;', 'transaction'),
 T(52, 'What do NOWAIT and SKIP LOCKED change about locking reads on MySQL 8.0.28?',
   'NOWAIT makes a locking read fail immediately when a requested row lock cannot be acquired; SKIP LOCKED omits locked rows instead of waiting. Both are available on MySQL 8.0.28 and are useful for queue-like workloads, not for a complete consistent report. They affect row-level lock waits, not every possible metadata or table lock wait.',
   'nowait|skip locked|queue|locking read',
   'START TRANSACTION; SELECT `Order ID` FROM orders ORDER BY `Order ID` LIMIT 1 FOR UPDATE SKIP LOCKED; ROLLBACK;', 'transaction'),
 T(53, 'How does optimistic locking prevent silently overwriting a concurrently changed row?',
   'Include the previously read version or value in the UPDATE predicate and check the affected-row outcome. If no row matches, the application must distinguish a conflict or missing row and retry or report it rather than overwriting blindly. This dump has no universal version column, so a production version-counter design would require an explicit schema change; a transaction alone does not define the conflict policy.',
   'optimistic locking|lost update|affected rows|version counter', '', 'transaction'),
 T(54, 'Why must a deadlock retry repeat the whole transaction rather than only its final statement?',
   'InnoDB rolls back a deadlock victim transaction, so retrying only the last statement can omit earlier work from the original unit. Retry the full transaction with bounded backoff and idempotent external effects; choose a consistent row-access order to reduce deadlocks. A lock wait timeout has different rollback behavior depending on configuration and must not be conflated with a detected deadlock.',
   'deadlock victim|whole transaction retry|lock timeout', '', 'transaction'),
 T(55, 'Can ROW_COUNT prove which rows were changed by an earlier statement in another session?',
   'ROW_COUNT refers to the most recent statement in the current connection, not global activity or a past statement in a different connection. DML affected-row semantics depend on the statement, and client options can distinguish matched from changed rows for updates. Inspect the outcome immediately and do not treat the number as a list of changed identifiers.',
   'row_count|connection scope|affected rows|matched rows',
   'START TRANSACTION; UPDATE orders SET Notes=Notes WHERE `Order ID`=30; SELECT ROW_COUNT(); ROLLBACK;', 'transaction'),
 T(56, 'When is a NOT EXISTS set-difference emulation different from EXCEPT DISTINCT for duplicate rows?',
   'NOT EXISTS filters left input rows without removing duplicates, whereas EXCEPT DISTINCT returns unique remaining rows. Add DISTINCT to the selected left columns and choose NULL-safe matching if emulating set semantics with nullable attributes. EXCEPT itself is unavailable on 8.0.28; it arrived in MySQL 8.0.31.',
   'except distinct emulation|duplicates|null safe|8.0.31',
   'SELECT DISTINCT customer.City FROM customers customer WHERE NOT EXISTS (SELECT 1 FROM suppliers supplier WHERE supplier.City<=>customer.City);', 'set_ops'),
 T(57, 'How can you emulate INTERSECT DISTINCT while retaining a common NULL value on 8.0.28?',
   'Use SELECT DISTINCT from one input with EXISTS against the other and compare nullable attributes with <=>. A plain equality or IN predicate does not retain a common NULL value, so it is not a complete nullable set-intersection emulation. Native INTERSECT requires MySQL 8.0.31 or later and therefore is not the exam-version main answer.',
   'intersect distinct emulation|null membership|8.0.31',
   'SELECT DISTINCT customer.City FROM customers customer WHERE EXISTS (SELECT 1 FROM suppliers supplier WHERE supplier.City<=>customer.City);', 'set_ops'),
 T(58, 'Why does inventory Transaction Type require a lookup rather than a Status filter?',
   'In this schema inventory transactions.Transaction Type stores the numeric ID of inventory transaction types, whose Type Name contains Purchased, Sold, On Hold or Waste. Inventory transactions has no Status column; order statuses belong to different tables and represent different concepts. Join the type lookup and filter Type Name, and state whether quantities are unsigned type totals or signed movements.',
   'inventory transaction type|type name|no status column|ledger',
   "SELECT kind.`Type Name`,SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` GROUP BY kind.`Type Name`;", 'inner_join'),
 T(59, 'Why do order-detail sales quantities and inventory Sold quantities not necessarily reconcile?',
   'Orders and the inventory ledger record different events and may differ by timing, cancellation, allocation or incomplete links. This dump has NULL sales-order links in inventory transactions, so matching the two systems by guessed IDs is unsupported. Compare independently aggregated product totals as a diagnostic, not as a claim about stock balances or transaction completeness.',
   'sales ledger reconciliation|null order links|inventory balance',
   'SELECT COUNT(*) ledger_rows,COUNT(`Customer Order ID`) linked_sales_rows,COUNT(`Purchase Order ID`) linked_purchase_rows FROM `inventory transactions`;', 'aggregate'),
 T(60, 'What evidence does execution-equivalent SQL on one dump provide, and what does it not prove?',
   'Matching main and alternative result multisets on the supplied dump is useful regression evidence, not proof that both queries match the question or agree on all possible data. Empty results, absent categories, NULL-only columns and missing ties can hide shared mistakes; review semantics and test counterexamples separately. Execution on MySQL 9.7 also does not certify 8.0.28 syntax or behavior, so maintain version notes and avoid newer features in main answers.',
   'execution verification|empty result|counterexample|version compatibility',
   'SELECT VERSION(),COUNT(*) FROM orders;', 'optimization'),
]
